/// What writing the server read on a picture (`zcore::art::Writing`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum Writing {
    Clean,
    Title,
    Other,
    Asian,
}

impl From<zcore::art::Writing> for Writing {
    fn from(w: zcore::art::Writing) -> Self {
        match w {
            zcore::art::Writing::Clean => Writing::Clean,
            zcore::art::Writing::Title => Writing::Title,
            zcore::art::Writing::Other => Writing::Other,
            zcore::art::Writing::Asian => Writing::Asian,
        }
    }
}

impl From<Writing> for zcore::art::Writing {
    fn from(w: Writing) -> Self {
        match w {
            Writing::Clean => zcore::art::Writing::Clean,
            Writing::Title => zcore::art::Writing::Title,
            Writing::Other => zcore::art::Writing::Other,
            Writing::Asian => zcore::art::Writing::Asian,
        }
    }
}

