/// A series (`zcore::manhwa::Comic`).
#[derive(Debug, uniffi::Record)]
pub struct ComicRecord {
    pub path: String,
    pub title: String,
    pub cover: String,
    pub thumb: String,
    pub rating: String,
}

/// A page of the catalogue (`zcore::manhwa::Shelf`).
#[derive(Debug, uniffi::Record)]
pub struct ShelfRecord {
    pub items: Vec<ComicRecord>,
    pub more: bool,
}

/// A catalogue page from the server (`zcore::manhwa::parse_catalog`).
#[uniffi::export]
pub fn manhwa_parse_catalog(body: String, page: u32, query: String, genre: String) -> Result<ShelfRecord, CoreError> {
    let shelf = zcore::manhwa::parse_catalog(&body, page, &query, &genre)?;
    let items = shelf
        .items
        .into_iter()
        .map(|c| ComicRecord { path: c.path, title: c.title, cover: c.cover, thumb: c.thumb, rating: c.rating })
        .collect();
    Ok(ShelfRecord { items, more: shelf.more })
}

/// A series' cover for a card, and for its own page (`zcore::manhwa::Comic::small`, `large`).
#[derive(Debug, uniffi::Record)]
pub struct Covers {
    pub small: String,
    pub large: String,
}

/// A series' covers (`zcore::manhwa::Comic::small`, `large`).
#[uniffi::export]
pub fn manhwa_covers(cover: String, thumb: String) -> Covers {
    let c = zcore::manhwa::Comic { cover, thumb, ..zcore::manhwa::Comic::default() };
    Covers { small: c.small().to_string(), large: c.large() }
}

/// A chapter's pages from the server, only Asura's own (`zcore::manhwa::parse_pages`).
#[uniffi::export]
pub fn manhwa_parse_pages(body: String) -> Result<Vec<String>, CoreError> {
    Ok(zcore::manhwa::parse_pages(&body)?)
}

