use zcore::downloads as dl;

use queue::{DownloadAct, DownloadState};

/// A chapter's folder name (`zcore::downloads::chapter_folder`).
#[uniffi::export]
pub fn chapter_folder(path: String) -> String {
    dl::chapter_folder(&path)
}

/// Why a download stopped, in the words every app shows (`zcore::downloads`).
#[derive(Debug, uniffi::Record)]
pub struct DownloadWords {
    pub cant: String,
    pub full: String,
    pub dropped: String,
    pub not_answering: String,
    pub cant_save: String,
    pub chapter_not_out: String,
    pub page_missing: String,
}

/// The download failure words (`zcore::downloads::CANT` and the rest).
#[uniffi::export]
pub fn download_words() -> DownloadWords {
    DownloadWords {
        cant: dl::CANT.into(),
        full: dl::FULL.into(),
        dropped: dl::DROPPED.into(),
        not_answering: dl::NOT_ANSWERING.into(),
        cant_save: dl::CANT_SAVE.into(),
        chapter_not_out: dl::CHAPTER_NOT_OUT.into(),
        page_missing: dl::PAGE_MISSING.into(),
    }
}

/// What a tap on one download's control does (`zcore::downloads::tap`).
#[uniffi::export]
pub fn download_tap(state: Option<DownloadState>) -> DownloadAct {
    dl::tap(state)
}

/// One of a batch: where it stands (None: not added) and how far along.
#[derive(Debug, uniffi::Record)]
pub struct BatchItem {
    pub state: Option<DownloadState>,
    pub share: f32,
}

/// A batch's button: what it does and says, and which of the batch a press acts on (indices).
#[derive(Debug, uniffi::Record)]
pub struct Batch {
    pub act: DownloadAct,
    pub label: String,
    pub targets: Vec<u32>,
}

/// A button for several downloads at once (`zcore::downloads::batch`, `batch_targets`).
#[uniffi::export]
pub fn download_batch(items: Vec<BatchItem>, one: bool) -> Batch {
    let pairs: Vec<(Option<dl::State>, f32)> = items.iter().map(|i| (i.state, i.share)).collect();
    let (act, label) = dl::batch(&pairs, one);
    let states: Vec<Option<dl::State>> = pairs.iter().map(|p| p.0).collect();
    let targets = dl::batch_targets(&states, act).into_iter().map(|i| i as u32).collect();
    Batch { act, label, targets }
}

/// A size as Downloads says it ("1.2 GB").
#[uniffi::export]
pub fn size_words(bytes: u64) -> String {
    dl::size_words(bytes)
}
